INSERT INTO `disc_questions` VALUES (1,1,'Mudah sepakat, fleksibel','Mudah mempercayai orang lain, terbuka','Suka tantangan, berani mengambil risiko','Penuh toleransi, saling menghargai','S','I','D','C',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(2,2,'Bicara halus, cenderung tenang dan diam','Berpandangan positif, berfokus pada masa depan','Senang menjadi pusat perhatian, ramah dan supel','Menjaga kedamaian, menciptakan keselarasan','C','D','I','S',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(3,3,'Memberi dorongan dan motivasi kepada orang lain','Mengejar kesempurnaan, teliti','Merasa nyaman menjadi bagian dari tim','Senang menetapkan target dan tujuan','I','C','S','D',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(4,4,'Mudah merasa frustrasi atau tertekan','Cenderung memendam perasaan pribadi','Senang mengungkapkan sudut pandang pribadi','Berani berbeda pendapat dan menghadapi oposisi','C','S','I','D',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(5,5,'Penuh semangat dan aktif berbicara','Cepat bertindak dan gigih/tekun','Berupaya menjaga keseimbangan dan keselarasan','Berusaha selalu patuh pada aturan dan prosedur','I','D','S','C',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(6,6,'Mampu mengatur waktu dengan efektif','Sering tergesa-gesa dan merasa terbebani','Peduli pada hubungan dan isu-isu sosial','Terbiasa menuntaskan setiap tugas hingga selesai','C','D','I','S',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(7,7,'Kurang menyukai perubahan yang mendadak','Cenderung berjanji secara berlebihan','Mengundurkan diri saat berada di bawah tekanan','Tidak ragu berkonfrontasi atau bertempur','S','I','C','D',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(8,8,'Mampu memotivasi orang lain dengan baik','Menjadi pendengar yang penuh perhatian','Memiliki kemampuan analisis yang kuat','Mampu membagi dan mendelegasikan tugas dengan baik','I','S','C','D',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(9,9,'Berorientasi pada pencapaian hasil akhir','Mengutamakan kebenaran dan presisi/ketelitian','Menyukai suasana yang ceria dan menyenangkan','Mengutamakan kerja sama dan pengerjaan bersama','D','C','I','S',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(10,10,'Cenderung terus maju tanpa kendali diri','Bertindak atau membeli berdasarkan impuls kata hati','Lebih memilih menunggu tanpa paksaan','Rela mengalah dan mengabaikan keinginan pribadi','C','D','S','I',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(11,11,'Ramah dan mudah berbaur dengan lingkungan baru','Memiliki keunikan dan cepat jenuh dengan rutinitas','Senang mengambil inisiatif untuk mengubah keadaan','Menyukai kejelasan dan hal-hal yang pasti','S','I','D','C',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(12,12,'Menghindari konflik dan cenderung mengalah','Berfokus pada rincian dan detail kecil','Siap menghadapi perubahan di menit-menit terakhir','Bersikap menuntut dan terkesan keras','S','C','I','D',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(13,13,'Selalu menghendaki kemajuan dan perkembangan','Mudah merasa puas dengan kondisi yang ada','Terbuka dalam memperlihatkan emosi/perasaan','Bersikap rendah hati dan bersahaja','D','S','I','C',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(14,14,'Bersikap tenang dan tidak banyak bicara','Memiliki pembawaan bahagia dan santai tanpa beban','Ramah, menyenangkan, dan berhati baik','Memiliki keberanian tinggi dan tidak gentar','C','I','S','D',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(15,15,'Senang meluangkan waktu berkualitas bersama teman','Selalu merencanakan masa depan dan bersiap diri','Menyukai perjalanan dan pengalaman petualangan baru','Mengharapkan penghargaan atas target yang diraih','S','C','I','D',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(16,16,'Cenderung kritis dan mempertanyakan aturan','Menganggap aturan berguna menciptakan keadilan','Memandang aturan sebagai hal yang membosankan','Menilai aturan memberikan rasa aman dan tertib','D','C','I','S',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(17,17,'Menghargai pendidikan dan wawasan kebudayaan','Terdorong oleh pencapaian dan ganjaran','Memprioritaskan keselamatan dan rasa aman','Senang bersosialisasi dan berorganisasi dalam kelompok','C','D','S','I',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(18,18,'Suka memegang kendali dan bertindak secara langsung','Bersemangat tinggi dan mudah bergaul','Bersikap konsisten dan dapat diprediksi','Bersikap penuh kehati-hatian dan selalu waspada','D','I','S','C',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(19,19,'Memiliki daya juang tinggi dan tidak mudah dikalahkan','Patuh pada instruksi dan arahan pimpinan','Mudah tersulut emosi atau menjadi pemicu suasana','Menyukai kerapian dan keteraturan yang terstruktur','D','S','I','C',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(20,20,'Saya yang akan memimpin mereka.','Saya siap mengeksekusi/melaksanakan tugas.','Saya yang akan membujuk/meyakinkan mereka.','Saya yang akan mengumpulkan data dan faktanya.','D','S','I','C',1,'2026-08-04 03:42:40','2026-08-04 03:42:40'),(21,21,'Mengutamakan kepentingan orang lain terlebih dahulu','Bersifat kompetitif dan menyukai tantangan','Selalu berpikir positif dan optimistis','Berpikir rasional, logis, dan terstruktur','S','D','I','C',1,'2026-08-04 03:42:41','2026-08-04 03:42:41'),(22,22,'Suka menyenangkan orang lain dan gampang sepakat','Ceria, lepas, dan penuh keseruan','Berani mengambil keputusan tanpa rasa ragu','Cenderung tenang, pendiam, dan hemat bicara','S','I','D','C',1,'2026-08-04 03:42:41','2026-08-04 03:42:41'),(23,23,'Menginginkan wewenang dan otoritas yang lebih besar','Senang mencari peluang dan kesempatan baru','Selalu berusaha menjauhi perselisihan/konflik','Membutuhkan panduan dan petunjuk yang jelas','D','I','S','C',1,'2026-08-04 03:42:41','2026-08-04 03:42:41'),(24,24,'Bisa diandalkan dan memegang kepercayaan','Berpikiran kreatif dan memiliki keunikan','Berfokus pada inti masalah dan orientasi hasil','Memegang standar tinggi serta mengutamakan akurasi','S','I','D','C',1,'2026-08-04 03:42:41','2026-08-04 03:42:41');
