--
-- Table structure for table `ist_questions`
--

DROP TABLE IF EXISTS `ist_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ist_questions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ist_subtest_id` bigint unsigned NOT NULL,
  `question_number` smallint unsigned NOT NULL,
  `display_order` smallint unsigned NOT NULL,
  `kind` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scored',
  `answer_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prompt` longtext COLLATE utf8mb4_unicode_ci,
  `image_disk` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_alt` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `example_explanation` longtext COLLATE utf8mb4_unicode_ci,
  `numeric_answer_key` decimal(20,6) DEFAULT NULL,
  `max_score` decimal(8,4) NOT NULL DEFAULT '1.0000',
  `difficulty` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '1',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ist_questions_subtest_kind_number_unique` (`ist_subtest_id`,`kind`,`question_number`),
  KEY `ist_questions_created_by_foreign` (`created_by`),
  KEY `ist_questions_updated_by_foreign` (`updated_by`),
  KEY `ist_questions_active_lookup_index` (`ist_subtest_id`,`kind`,`is_active`),
  CONSTRAINT `ist_questions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ist_questions_ist_subtest_id_foreign` FOREIGN KEY (`ist_subtest_id`) REFERENCES `ist_subtests` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ist_questions_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=227 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

