DROP TABLE IF EXISTS `ist_subtests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ist_subtests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sequence` tinyint unsigned NOT NULL,
  `question_count` smallint unsigned NOT NULL,
  `default_answer_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instruction_content` longtext COLLATE utf8mb4_unicode_ci,
  `memorization_content` longtext COLLATE utf8mb4_unicode_ci,
  `duration_seconds` smallint unsigned NOT NULL,
  `memorization_seconds` smallint unsigned NOT NULL DEFAULT '0',
  `answering_seconds` smallint unsigned NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ist_subtests_code_unique` (`code`),
  UNIQUE KEY `ist_subtests_sequence_unique` (`sequence`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
