  `answer_key_snapshot` json NOT NULL,
  `max_score` decimal(8,4) NOT NULL,
  `difficulty` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ist_test_questions_subtest_order_unique` (`ist_test_subtest_id`,`display_order`),
  KEY `ist_test_questions_source_question_id_index` (`source_question_id`),
  CONSTRAINT `ist_test_questions_ist_test_subtest_id_foreign` FOREIGN KEY (`ist_test_subtest_id`) REFERENCES `ist_test_subtests` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ist_test_questions_source_question_id_foreign` FOREIGN KEY (`source_question_id`) REFERENCES `ist_questions` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1913 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
